import{_ as s,o as t,c as a,a2 as n}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"TUI Guide","description":"","frontmatter":{},"headers":[],"relativePath":"liteshield-xdp/user-guide/tui.md","filePath":"liteshield-xdp/user-guide/tui.md","lastUpdated":null}'),i={name:"liteshield-xdp/user-guide/tui.md"};function o(d,e,l,r,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="tui-guide" tabindex="-1">TUI Guide <a class="header-anchor" href="#tui-guide" aria-label="Permalink to &quot;TUI Guide&quot;">​</a></h1><p>LiteShield ships a built-in live status screen — plain text with ANSI colors, no TUI frameworks, no dependencies. It starts automatically with <code>sudo liteshield load</code> and refreshes once per second.</p><nav class="table-of-contents"><ul><li><a href="#launching">Launching</a></li><li><a href="#layout">Layout</a></li><li><a href="#color-theme">Color Theme</a></li><li><a href="#what-each-section-shows">What Each Section Shows</a><ul><li><a href="#status-bar">Status bar</a></li><li><a href="#throughput">Throughput</a></li><li><a href="#packets">Packets</a></li><li><a href="#defense">Defense</a></li></ul></li><li><a href="#keyboard-controls">Keyboard Controls</a></li><li><a href="#static-mode-stats-off">Static Mode (--stats-off)</a></li><li><a href="#systemd-and-the-tui">systemd and the TUI</a></li></ul></nav><hr><h2 id="launching" tabindex="-1">Launching <a class="header-anchor" href="#launching" aria-label="Permalink to &quot;Launching&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # attach + live screen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stats-off</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # attach + static screen (no per-second polling)</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">The TUI is not the firewall</p><p>The XDP program is attached before the first frame renders and <strong>stays attached after you quit</strong>. The TUI is a read-only view over the pinned BPF maps — quitting never disables protection.</p></div><hr><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  _     _ _       ____  _     _      _     _   __  ______  ____</span></span>
<span class="line"><span> | |   (_) |_ ___/ ___|| |__ (_) ___| | __| |  \\ \\/ /  _ \\|  _ \\</span></span>
<span class="line"><span> | |   | | __/ _ \\___ \\| &#39;_ \\| |/ _ \\ |/ _  |   \\  /| | | | |_) |</span></span>
<span class="line"><span> | |___| | ||  __/___) | | | | |  __/ | (_| |   /  \\| |_| |  __/</span></span>
<span class="line"><span> |_____|_|\\__\\___|____/|_| |_|_|\\___|_|\\__,_|  /_/\\_\\____/|_|</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ◆ LiteShield XDP ACTIVE  eth0  up 01:12:44</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ▸ Throughput</span></span>
<span class="line"><span>   PPS  84.2k    BPS  512.30 MB/s</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ▸ Packets</span></span>
<span class="line"><span>   Passed   301442981</span></span>
<span class="line"><span>   Dropped  1204556</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ▸ Defense</span></span>
<span class="line"><span>   Active bans  3</span></span>
<span class="line"><span>   Rule drops   SYN 812110 | UDP 390021 | ICMP 2425 | PPS 0 | NewSrc 0</span></span>
<span class="line"><span>   Lists        whitelist 1204 | blacklist 88</span></span>
<span class="line"><span></span></span>
<span class="line"><span> Press Ctrl-C to exit — LiteShield keeps running.</span></span></code></pre></div><p>The screen has a banner, a status bar, and three sections:</p><table tabindex="0"><thead><tr><th>Section</th><th>Shows</th></tr></thead><tbody><tr><td><strong>Status bar</strong></td><td><code>ACTIVE</code> indicator, protected interface, uptime (since <code>load</code>)</td></tr><tr><td><strong>Throughput</strong></td><td>Live packets/sec and bytes/sec, computed from per-second counter deltas</td></tr><tr><td><strong>Packets</strong></td><td>Cumulative passed and dropped counters since attach</td></tr><tr><td><strong>Defense</strong></td><td>Active auto-bans, per-rule drop counters, whitelist/blacklist hit counts</td></tr></tbody></table><hr><h2 id="color-theme" tabindex="-1">Color Theme <a class="header-anchor" href="#color-theme" aria-label="Permalink to &quot;Color Theme&quot;">​</a></h2><p>The theme is deliberately minimal — <strong>blue, red, white</strong>, with semantic accents:</p><table tabindex="0"><thead><tr><th>Element</th><th>Color</th><th>Meaning</th></tr></thead><tbody><tr><td>Banner, section markers (<code>▸</code>), interface name</td><td><strong>Blue</strong> (bold)</td><td>Branding / structure</td></tr><tr><td>Values (PPS, BPS, counters)</td><td><strong>White</strong> (bold)</td><td>Primary data</td></tr><tr><td><code>ACTIVE</code></td><td>Green</td><td>Program attached and enforcing</td></tr><tr><td>Dropped packets</td><td><strong>Red</strong> when &gt; 0, green when 0</td><td>Drops are happening vs. all clean</td></tr><tr><td>Active bans</td><td>Yellow when &gt; 0, green when 0</td><td>Attention vs. idle</td></tr><tr><td>Labels, hints, uptime</td><td>Gray</td><td>Secondary information</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Reading drops at a glance</p><p>If <strong>Dropped</strong> is green, nothing is being filtered. Red means LiteShield is actively mitigating — check the <strong>Rule drops</strong> line to see <em>which</em> rule is firing (a SYN flood shows up under <code>SYN</code>, a reflection attack under <code>UDP</code>).</p></div><hr><h2 id="what-each-section-shows" tabindex="-1">What Each Section Shows <a class="header-anchor" href="#what-each-section-shows" aria-label="Permalink to &quot;What Each Section Shows&quot;">​</a></h2><h3 id="status-bar" tabindex="-1">Status bar <a class="header-anchor" href="#status-bar" aria-label="Permalink to &quot;Status bar&quot;">​</a></h3><p><code>◆ LiteShield XDP ACTIVE eth0 up 01:12:44</code></p><ul><li><strong>ACTIVE</strong> — the XDP program is attached and the <code>enabled</code> flag is set in <code>config_map</code></li><li><strong>Interface</strong> — the attach point from your config, with its mode shown at load time (<code>native</code> or <code>generic</code>)</li><li><strong>Uptime</strong> — time since this <code>load</code> invocation (not since boot)</li></ul><h3 id="throughput" tabindex="-1">Throughput <a class="header-anchor" href="#throughput" aria-label="Permalink to &quot;Throughput&quot;">​</a></h3><p>Per-second rates derived from deltas between consecutive <code>global_stats_map</code> reads. <code>PPS</code> uses compact suffixes (<code>84.2k</code>, <code>1.20M</code>); <code>BPS</code> uses binary units (<code>512.30 MB/s</code>).</p><h3 id="packets" tabindex="-1">Packets <a class="header-anchor" href="#packets" aria-label="Permalink to &quot;Packets&quot;">​</a></h3><p>Cumulative counters since the program was attached. <code>Passed + Dropped</code> equals total <code>rx</code> packets the parser recognized as IP traffic.</p><h3 id="defense" tabindex="-1">Defense <a class="header-anchor" href="#defense" aria-label="Permalink to &quot;Defense&quot;">​</a></h3><ul><li><strong>Active bans</strong> — sources currently inside their auto-ban window (from threshold violations) plus manual timed bans still in effect</li><li><strong>Rule drops</strong> — cumulative drops attributed to each rule: <code>SYN</code> / <code>UDP</code> / <code>ICMP</code> / <code>PPS</code> (per-IP thresholds) and <code>NewSrc</code> (global new-source limit)</li><li><strong>Lists</strong> — cumulative packets matched by the whitelist (passed) and blacklist (dropped)</li></ul><hr><h2 id="keyboard-controls" tabindex="-1">Keyboard Controls <a class="header-anchor" href="#keyboard-controls" aria-label="Permalink to &quot;Keyboard Controls&quot;">​</a></h2><p>There is exactly one control — by design:</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl-C</code></td><td>Exit the status screen. The XDP program <strong>keeps running</strong>.</td></tr></tbody></table><p>The cursor is hidden while the screen renders and restored on exit.</p><div class="warning custom-block"><p class="custom-block-title">Want to actually stop protection?</p><p><code>Ctrl-C</code> is not enough. Run <code>sudo liteshield unload</code>, or <code>sudo systemctl stop liteshield-loader.service</code> if you&#39;re running under systemd.</p></div><hr><h2 id="static-mode-stats-off" tabindex="-1">Static Mode (<code>--stats-off</code>) <a class="header-anchor" href="#static-mode-stats-off" aria-label="Permalink to &quot;Static Mode (\`--stats-off\`)&quot;">​</a></h2><p>On very small machines (or over slow serial/SSH links) you can skip the per-second map polling entirely:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stats-off</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LiteShield XDP is protecting eth0 (native mode).</span></span>
<span class="line"><span>XDP stays loaded after you quit. Use \`liteshield unload\` to stop.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Stats display disabled (--stats-off). Press Ctrl-C to exit.</span></span></code></pre></div><p>The firewall enforces identically — only the display is static. Use <code>sudo liteshield status</code> from another terminal for on-demand counters.</p><hr><h2 id="systemd-and-the-tui" tabindex="-1">systemd and the TUI <a class="header-anchor" href="#systemd-and-the-tui" aria-label="Permalink to &quot;systemd and the TUI&quot;">​</a></h2><p>The installed service runs headless:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/usr/local/bin/liteshield load --no-tui --config /etc/liteshield/liteshield.yaml</span></span></code></pre></div><p><code>--no-tui</code> attaches the program and exits; the BPF link stays pinned at <code>/sys/fs/bpf/liteshield/link</code>, so protection persists with no process at all. To watch stats on a systemd-managed host, use <code>sudo liteshield status</code> for a one-shot snapshot — running <code>liteshield load</code> while already loaded fails with <code>LiteShield is already loaded (run </code>liteshield unload<code> first)</code>.</p>`,45)])])}const g=s(i,[["render",o]]);export{u as __pageData,g as default};
